{"content": "const fs = require('node:fs');
const lines = fs.readFileSync(process.argv[2], 'utf8').split('\n').filter((l) => l.length > 0);
console.log('lines:', lines.length);
const events = [];
let bad = 0;
for (let i = 1; i < lines.length; i += 1) {
  try {
    events.push(JSON.parse(lines[i]));
  } catch (e) {
    bad += 1;
  }
}
console.log('parsed:', events.length, 'bad:', bad);
console.log('first seq', events[0].seq, 'last seq', events[events.length - 1].seq);
// find gaps / duplicates
let gaps = 0, dup = 0;
for (let i = 1; i < events.length; i += 1) {
  if (events[i].seq !== events[i - 1].seq + 1) {
    if (events[i].seq === events[i - 1].seq) dup += 1; else { gaps += 1; if (gaps < 10) console.log('gap at index', i, ': prev', events[i - 1].seq, 'next', events[i].seq); }
  }
}
console.log('gaps:', gaps, 'dups:', dup);
const bySeq = new Map();
for (const e of events) if (!bySeq.has(e.seq)) bySeq.set(e.seq, e);
for (const s of [11, 12, 13, 8514, 8515, 8516, 8517]) {
  const e = bySeq.get(s);
  console.log('---', s, e === undefined ? 'MISSING' : `${e.type} surfaceOp=${JSON.stringify(e.surfaceOp)}`);
}
const replaces = events.filter((e) => e.surfaceOp && e.surfaceOp !== 'append');
console.log('replaces:', replaces.length);
for (const r of replaces) console.log('replace seq', r.seq, r.type, r.surfaceOp.startSeq + '-' + r.surfaceOp.endSeq);
