const lines = fs.readFileSync(process.argv[2], 'utf8').split('\n').filter((l) => l.length > 0);
const chunkTypes = new Set(['reasoning-chunks', 'tool-call-chunks', 'text-chunks']);
let expected = 0;
let violations = [];
let chunkRecords = 0;
let chunkEvents = 0;
let explicit = 0;
for (let i = 1; i < lines.length; i += 1) {
  const r = JSON.parse(lines[i]);
  if (chunkTypes.has(r.type)) {
    chunkRecords += 1;
    const n = r.data.dt.length;
    chunkEvents += n;
    if (r.seq0 !== expected && violations.length < 10) violations.push({ line: i, type: r.type, seq0: r.seq0, expected, n });
    expected = r.seq0 + n;
  } else {
    explicit += 1;
    if (r.seq !== expected && violations.length < 10) violations.push({ line: i, type: r.type, seq: r.seq, expected });
    expected = (typeof r.seq === 'number' ? r.seq : expected) + 1;
  }
}
console.log({ chunkRecords, chunkEvents, explicit, finalExpected: expected, violations });
