{"content": "// Replay the decoded session log through the live-stats surface fold logic.
const fs = require('node:fs');

const SURFACE = new Set(['system/message', 'user/message', 'assistant/message', 'tool/result']);
const lines = fs.readFileSync(process.argv[2], 'utf8').split('\n').filter((l) => l.length > 0);
const surface = new Map();
let surfaceTokens = 0;
let surfaceEvents = 0;
let appends = 0;
let replaces = 0;
const problems = [];
const noOp = [];
for (let i = 1; i < lines.length; i += 1) {
  let e;
  try { e = JSON.parse(lines[i]); } catch (err) { continue; }
  if (!SURFACE.has(e.type)) continue;
  if (e.surfaceOp === undefined) { noOp.push({ line: i, seq: e.seq, type: e.type }); continue; }
  surfaceEvents += 1;
  if (e.surfaceOp === 'append') {
    appends += 1;
    surface.set(e.seq, 1);
    surfaceTokens += 1;
    continue;
  }
  replaces += 1;
  const op = e.surfaceOp;
  const ok = surface.has(op.start) && surface.has(op.end) && op.start <= op.end;
  if (!ok) {
    problems.push({ line: i, seq: e.seq, type: e.type, start: op.start, end: op.end, hasStart: surface.has(op.start), hasEnd: surface.has(op.end) });
    if (problems.length > 5) break;
  }
  for (const key of [...surface.keys()]) {
    if (key >= op.start && key <= op.end) surface.delete(key);
  }
  surface.set(e.seq, 1);
}
console.log({ surfaceEvents, appends, replaces, finalSurfaceSize: surface.size });
console.log('message events without surfaceOp:', noOp.length, noOp.slice(0, 20));
console.log('problems:', problems);
", "file_path": "C:\Users\HUAWEI\Desktop\_session-inspect\replay.js"}

