export interface State {
  ...
  /** Surface node seq -> estimated tokens, keyed for lookup only. */
  surface: Map<number, number>
  /** Surface node seqs in model-visible order (the authority for replacement ranges). */
  surfaceOrder: number[]
  surfaceTokens: number
}
