applySurface:
```ts
function applySurface(state, event, spec): Pick<State, 'surface' | 'surfaceOrder' | 'surfaceTokens'> {
  const tokens = estimateMessageTokens(surfaceMessage(event), spec)
  if (event.surfaceOp === 'append') {
    state.surface.set(event.seq, tokens)
    state.surfaceOrder.push(event.seq)
    return { surface: state.surface, surfaceOrder: state.surfaceOrder, surfaceTokens: state.surfaceTokens + tokens }
  }
  // A replacement names the two current surface nodes that bound the range it
  // shadows; the authority is the surface ORDER, not seq arithmetic: a
  // replacement keeps its anchor's position, so a node with a smaller seq can
  // sit after one with a larger seq (migrated system/message heads do exactly
  // that). Mirrors the Session surface fold (indexOf + splice).
  const operation = event.surfaceOp
  const startIdx = state.surfaceOrder.indexOf(operation.startSeq)
  const endIdx = state.surfaceOrder.indexOf(operation.endSeq)
  if (startIdx === -1 || endIdx === -1 || startIdx > endIdx) throw new Error('live-stats: replace at seq ' + event.seq + ' has invalid current range ' + operation.startSeq + '-' + operation.endSeq)
  let removed = 0
  for (let index = startIdx; index <= endIdx; index += 1) {
    const seq = state.surfaceOrder[index]
    removed += state.surface.get(seq) ?? 0
    state.surface.delete(seq)
  }
  state.surfaceOrder.splice(startIdx, endIdx - startIdx + 1, event.seq)
  state.surface.set(event.seq, tokens)
  return { surface: state.surface, surfaceOrder: state.surfaceOrder, surfaceTokens: state.surfaceTokens - removed + tokens }
}
