{"content": "import fs from 'node:fs';
const { header, inheritedEventCount, events } = JSON.parse(fs.readFileSync('events-v4.json', 'utf8'));
const session = await import('file:///C:/Users/HUAWEI/node_modules/@deepseek-ai/dsh-session/lib/index.js');
const { createLiveTokenUsageProjectionDefinition, resolveEstimatorConfig } = await import(
  'file:///C:/Users/HUAWEI/node_modules/@captain1275/dsh-live-stats/lib/index.js'
);

// Authoritative: dsh-session surface fold (indexOf + splice).
const s = session.Session.fromRestore(session.SessionId(header.id), events, header, session.SessionLogOffset(inheritedEventCount), 'detached');
let authoritative;
try {
  authoritative = [...s.surface.nodes];
  console.log('authoritative nodes:', authoritative.length);
} catch (error) {
  console.log('AUTHORITATIVE FOLD FAILED:', error.message);
}

// Plugin fold (patched).
const definition = createLiveTokenUsageProjectionDefinition(resolveEstimatorConfig({}));
let state = definition.init();
for (const event of events) state = definition.apply(state, event);
console.log('plugin nodes:', state.surfaceOrder.length, 'map size:', state.surface.size);

if (authoritative !== undefined) {
  const same = authoritative.length === state.surfaceOrder.length
    && authoritative.every((seq, index) => seq === state.surfaceOrder[index]);
  console.log('ORDER+IDENTITY MATCH:', same);
  if (!same) {
    for (let i = 0; i < Math.max(authoritative.length, state.surfaceOrder.length); i += 1) {
      if (authoritative[i] !== state.surfaceOrder[i]) { console.log('first divergence at', i, authoritative[i], state.surfaceOrder[i]); break; }
    }
  }
  console.log('first 8 authoritative:', authoritative.slice(0, 8).join(','), '| plugin:', state.surfaceOrder.slice(0, 8).join(','));
  const missing = authoritative.filter((seq) => !state.surface.has(seq));
  const extra = state.surfaceOrder.filter((seq) => !authoritative.includes(seq));
  console.log('missing in plugin:', missing.length, missing.slice(0, 5), 'extra:', extra.length, extra.slice(0, 5));
}
