{"content": "// Scan stored sessions: migrate each log to v4 and compare the OLD numeric-range
// surface fold (live-stats <= 0.4.0) with the positional fold the Session uses.
// Reports only the interesting sessions: those whose numeric fold diverges or throws.
import fs from 'node:fs';
import path from 'node:path';
import z from 'node:zlib';

const ZSTD_MAGIC = 4247762216;
function scanZstdFrames(buffer) {
  const frames = [];
  let offset = 0;
  while (offset < buffer.length) {
    const start = offset;
    if (buffer.length - offset < 4) break;
    if (buffer.readUInt32LE(offset) !== ZSTD_MAGIC) throw new Error(`invalid frame magic at byte ${offset}`);
    offset += 4;
    const descriptor = buffer.readUInt8(offset);
    offset += 1;
    const contentSizeFlag = descriptor >>> 6;
    const singleSegment = (descriptor & 32) !== 0;
    const checksum = (descriptor & 4) !== 0;
    const dictionaryFlag = descriptor & 3;
    const dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag;
    const contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : 1 << contentSizeFlag;
    offset += (singleSegment ? 0 : 1) + dictionaryBytes + contentSizeBytes;
    for (;;) {
      if (buffer.length - offset < 3) throw new Error('torn frame');
      const blockHeader = buffer.readUIntLE(offset, 3);
      offset += 3;
      const lastBlock = (blockHeader & 1) !== 0;
      const blockType = (blockHeader >>> 1) & 3;
      const blockSize = blockHeader >>> 3;
      offset += blockType === 1 ? 1 : blockSize;
      if (lastBlock) break;
    }
    if (checksum) offset += 4;
    frames.push({ start, end: offset });
  }
  return frames;
}

const { createSessionFormatCatalogWithChildren } = await import(
  'file:///C:/Users/HUAWEI/node_modules/@deepseek-ai/dsh-session-format-catalog/lib/index.js'
);

const files = process.argv.slice(2);
const report = [];
for (const file of files) {
  const id = path.basename(path.dirname(file));
  const entry = { id, file, status: 'ok' };
  try {
    const buf = fs.readFileSync(file);
    const frames = scanZstdFrames(buf);
    const chunks = frames.map((f) => z.zstdDecompressSync(buf.subarray(f.start, f.end)));
    const lines = Buffer.concat(chunks).toString('utf8').split('\n').filter((l) => l.length > 0);
    const header = JSON.parse(lines[0]);
    const catalog = createSessionFormatCatalogWithChildren([]);
    const restore = catalog.createRestore(header, { recovery: 'strict', validation: 'transformed' });
    for (let i = 1; i < lines.length; i += 1) restore.decodeRow(JSON.parse(lines[i]));
    const { events } = restore.finish();

    // positional fold (authority) + numeric fold (old plugin)
    const order = [];
    const tokens = new Map();
    let divergences = 0;
    let oldThrows = 0;
    let oldErrorAt = null;
    for (const event of events) {
      if (event.surfaceOp === undefined) continue;
      if (event.surfaceOp === 'append') { order.push(event.seq); tokens.set(event.seq, 1); continue; }
      const op = event.surfaceOp;
      const startIdx = order.indexOf(op.startSeq);
      const endIdx = order.indexOf(op.endSeq);
      if (startIdx === -1 || endIdx === -1 || startIdx > endIdx) { entry.status = 'positional-invalid'; break; }
      const positionalRemoved = order.slice(startIdx, endIdx + 1);
      const numericRemoved = [...tokens.keys()].filter((seq) => seq >= op.startSeq && seq <= op.endSeq);
      if (positionalRemoved.length !== numericRemoved.length || positionalRemoved.some((seq) => !numericRemoved.includes(seq))) {
        divergences += 1;
        oldThrows += 1;
        oldErrorAt ??= { seq: event.seq, type: event.type, op, missing: positionalRemoved.filter((seq) => !numericRemoved.includes(seq)).slice(0, 3) };
      }
      for (const seq of numericRemoved) tokens.delete(seq);
      if (divergences > 0 && oldThrows === 1) {
        // The old fold is already broken for this session; report and stop simulating it.
      }
      // continue with the positional fold so later events stay mappable
      for (const seq of positionalRemoved) tokens.delete(seq);
      order.splice(startIdx, endIdx - startIdx + 1, event.seq);
    }
    entry.events = events.length;
    entry.surfaceNodes = order.length;
    entry.divergentReplaces = divergences;
    entry.wouldOldFoldThrow = divergences > 0;
    entry.firstOldFailure = oldErrorAt;
  } catch (error) {
    entry.status = 'scan-failed';
    entry.error = error.message;
  }
  report.push(entry);
  console.log(JSON.stringify(entry));
}
fs.writeFileSync('session-scan.json', JSON.stringify(report, null, 2));
