import io
from pptx import Presentation

SRC = r'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
DST = r'C:\Users\HUAWEI\Desktop\_ppt\spot.txt'

prs = Presentation(SRC)
out = io.open(DST, 'w', encoding='utf-8')

for idx in (0, 1, 2, 6, 9, 12, 13, 17, 18, 26, 27, 30):
    s = prs.slides[idx]
    out.write(u'\n### slide %d\n' % (idx + 1))
    for sh in s.shapes:
        try:
            if sh.has_text_frame and sh.text_frame.text.strip():
                runs = []
                for p in sh.text_frame.paragraphs:
                    for r in p.runs:
                        col = None
                        try:
                            if r.font.color and r.font.color.type is not None:
                                col = str(r.font.color.rgb)
                        except Exception:
                            col = None
                        runs.append(u'[%s|%s]' % (r.text, col))
                out.write(u'  id=%-4d %s\n' % (sh.shape_id, u' '.join(runs)[:150]))
        except Exception:
            pass
        try:
            if sh.has_table:
                out.write(u'  TABLE rows=%d cols=%d\n' % (len(sh.table.rows), len(sh.table.columns)))
                for ri in range(min(3, len(sh.table.rows))):
                    cells = [sh.table.cell(ri, ci).text_frame.text for ci in range(len(sh.table.columns))]
                    out.write(u'    r%d %s\n' % (ri, u' | '.join(cells)))
                out.write(u'    row heights(in): %s\n'
                          % [round(r.height / 914400.0, 2) for r in sh.table.rows][:6])
        except Exception:
            pass
out.close()
print('ok')
