{"content": "$ErrorActionPreference = 'Stop'
$path = 'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
$pp = $null; $pres = $null
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($path, $true, $false, $false)
    Write-Output ("slides=" + $pres.Slides.Count)
    # transitions
    $tr = @()
    foreach ($i in 1..3) { $tr += $pres.Slides.Item($i).SlideShowTransition.EntryEffect }
    Write-Output ("entry effects 1..3: " + ($tr -join ','))
    # text overflow via real metrics (points)
    $issues = 0
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $s = $pres.Slides.Item($i)
        foreach ($sh in $s.Shapes) {
            try {
                if (-not $sh.HasTextFrame) { continue }
                if (-not $sh.TextFrame.HasText) { continue }
                $tr2 = $sh.TextFrame.TextRange
                $txt = $tr2.Text
                if ([string]::IsNullOrWhiteSpace($txt)) { continue }
                $bh = $tr2.BoundHeight
                $bw = $tr2.BoundWidth
                $h = $sh.Height
                $w = $sh.Width
                if (($bh -gt $h + 3) -or ($bw -gt $w + 3)) {
                    $issues++
                    $short = $txt -replace "`r", ' / '
                    if ($short.Length -gt 42) { $short = $short.Substring(0, 42) }
                    Write-Output ("s{0} id{1} '{2}' box={3:N0}x{4:N0} text={5:N0}x{6:N0}" -f $i, $sh.Id, $short, $w, $h, $bw, $bh)
                }
            } catch { }
        }
    }
    Write-Output ("overflow issues: " + $issues)
} catch {
    Write-Output ("ERR: " + $_.Exception.Message)
} finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}
