{"content":"import os

import machine
import sdcard
from machine import Pin, SoftSPI

mounted = False
try:
    names = os.listdir("/sd")
    mounted = True
    print("already mounted, files=%d" % len(names))
except Exception as e:
    print("not mounted (%s) -> try mount" % e)

if not mounted:
    for hz in (100000, 200000, 400000):
        try:
            spi = SoftSPI(baudrate=hz, polarity=0, phase=0,
                          sck=Pin(21), mosi=Pin(47),
                          miso=Pin(4, Pin.IN, Pin.PULL_UP))
            sd = sdcard.SDCard(spi, Pin(14, Pin.OUT), hz)
            try:
                os.umount("/sd")
            except Exception:
                pass
            os.mount(sd, "/sd")
            print("mounted @%d" % hz)
            names = os.listdir("/sd")
            break
        except Exception as e:
            print("  mount @%d err %s" % (hz, e))

try:
    names = os.listdir("/sd")
except Exception as e:
    names = []
    print("listdir err", e)

for n in sorted(names):
    if not n.lower().endswith(".csv"):
        continue
    try:
        sz = os.stat("/sd/" + n)[6]
        f = open("/sd/" + n)
        head = f.read(70)
        f.close()
        print("%-18s %8d B  %s" % (n, sz, repr(head[:40])))
    except Exception as e:
        print("%-18s ERR %s" % (n, e))","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\sd_verify.py"}

