<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>P4X 地面站 · 连接即启动</title>
<style>
  :root{ --fg:#e6ecf3; --dim:#93a1b1; --acc:#3ddc97; --warn:#ffb454; --bad:#ff6b6b; --line:rgba(255,255,255,.10); }
  *{box-sizing:border-box}
  body{
    margin:0; min-height:100vh; color:var(--fg);
    background:radial-gradient(1100px 620px at 70% 8%, #24303e 0%, #151c24 45%, #0a0e13 100%);
    font:13px/1.6 "Segoe UI","Microsoft YaHei",system-ui,sans-serif;
  }
  .wrap{max-width:1080px;margin:0 auto;padding:22px 18px 40px}
  h1{font-size:17px;margin:0 0 4px;letter-spacing:.4px}
  .sub{color:var(--dim);font-size:12px;margin-bottom:16px}
  .card{background:rgba(16,21,28,.82);border:1px solid var(--line);border-radius:14px;padding:14px 16px;margin-bottom:14px;box-shadow:0 16px 44px rgba(0,0,0,.4)}
  .row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
  button{
    font:inherit;font-size:12.5px;color:var(--fg);background:rgba(255,255,255,.06);
    border:1px solid var(--line);border-radius:10px;padding:8px 14px;cursor:pointer;transition:.15s
  }
  button:hover:not(:disabled){background:rgba(61,220,151,.15);border-color:rgba(61,220,151,.5)}
  button:disabled{opacity:.4;cursor:not-allowed}
  button.primary{background:rgba(61,220,151,.2);border-color:rgba(61,220,151,.65);color:#d6fff0;font-weight:600}
  label.chk{display:flex;gap:6px;align-items:center;color:var(--dim);font-size:12px;cursor:pointer}
  .chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
  .chip{display:flex;gap:6px;align-items:center;font-size:12px;color:var(--dim);
        background:rgba(255,255,255,.04);border:1px solid var(--line);border-radius:999px;padding:4px 11px}
  .dot{width:7px;height:7px;border-radius:50%;background:#55606d;transition:.2s}
  .dot.ok{background:var(--acc);box-shadow:0 0 8px rgba(61,220,151,.8)}
  .dot.wait{background:var(--warn);box-shadow:0 0 8px rgba(255,180,84,.8)}
  .dot.bad{background:var(--bad);box-shadow:0 0 8px rgba(255,107,107,.8)}
  pre#log{
    margin:0;height:340px;overflow:auto;background:#05080b;border:1px solid var(--line);
    border-radius:10px;padding:12px;font:12px/1.55 Consolas,"Cascadia Mono",monospace;color:#b9c9d8;
    white-space:pre-wrap;word-break:break-all
  }
  .hint{color:var(--dim);font-size:11.5px;margin-top:8px;line-height:1.7}
  code{background:rgba(255,255,255,.07);padding:1px 5px;border-radius:4px;font-size:11.5px}
</style>
</head>
<body>
<div class="wrap">
  <h1>P4X 地面站 · 连接即启动</h1>
  <div class="sub">点「连接」→ 选 ESP32 的串口（303A:1001）→ 自动等 NSH 起来 → 检查 <code>p4x_gs</code>，没跑就拉起来。</div>

  <div class="card">
    <div class="row">
      <button id="btnConn" class="primary">连接并启动</button>
      <button id="btnStatus" disabled>只看状态</button>
      <button id="btnRestart" disabled>重启 App</button>
      <button id="btnDisc" disabled>断开</button>
      <button id="btnClear">清屏</button>
      <label class="chk"><input type="checkbox" id="autoStart" checked> 连接后自动启动</label>
    </div>
    <div class="chips">
      <span class="chip"><span class="dot" id="dPort"></span>串口 <b id="tPort">未连接</b></span>
      <span class="chip"><span class="dot" id="dNsh"></span>NSH <b id="tNsh">—</b></span>
      <span class="chip"><span class="dot" id="dApp"></span>p4x_gs <b id="tApp">—</b></span>
    </div>
    <div class="hint">
      打开串口会让板子复位一次（这是硬件特性，文档里记过），大约 12 秒后 App 自己会起；脚本会等它。
      若浏览器不给串口权限，用同目录的 <code>网页启动.bat</code>（走 localhost）。
    </div>
  </div>

  <div class="card">
    <pre id="log">准备就绪。点「连接并启动」开始。\n</pre>
  </div>
</div>

<script>
const $ = id => document.getElementById(id);
const logEl = $('log');
let port = null, reader = null, writer = null, reading = false;
let sawNsh = false;

function log(msg, cls) {
  const t = new Date().toLocaleTimeString();
  logEl.textContent += `[${t}] ${msg}\n`;
  if (logEl.textContent.length > 200000) logEl.textContent = logEl.textContent.slice(-120000);
  logEl.scrollTop = logEl.scrollHeight;
}
function raw(text) {           // 串口原始输出
  logEl.textContent += text;
  logEl.scrollTop = logEl.scrollHeight;
}
function setDot(dot, state, text, el) {
  dot.className = 'dot' + (state ? ' ' + state : '');
  if (el && text !== undefined) el.textContent = text;
}
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function write(cmd) {
  if (!writer) return false;
  await writer.write(new TextEncoder().encode(cmd + '\n'));
  log('→ ' + cmd);
  return true;
}

async function connect(autoStart) {
  if (!('serial' in navigator)) {
    log('这个浏览器不支持 Web Serial，请用 Edge / Chrome 打开。', 'bad');
    return;
  }
  try {
    port = await navigator.serial.requestPort();
  } catch (e) { log('取消选择串口。'); return; }

  try {
    await port.open({ baudRate: 115200 });
  } catch (e) { log('打不开串口：' + e.message + '（可能被别的程序占着）', 'bad'); return; }

  // 拉低 DTR/RTS，别把芯片压在复位态
  try { await port.setSignals({ dataTerminalReady: false, requestToSend: false }); } catch (e) {}

  setDot($('dPort'), 'ok', (port.getInfo().usbVendorId === 0x303a ? 'ESP32 USB' : '串口'), $('tPort'));
  setDot($('dNsh'), 'wait', '等待中', $('tNsh'));
  setDot($('dApp'), '', '—', $('tApp'));
  ['btnStatus', 'btnRestart', 'btnDisc'].forEach(i => $(i).disabled = false);
  $('btnConn').disabled = true;
  sawNsh = false;

  const dec = new TextDecoderStream();
  port.readable.pipeTo(dec.writable).catch(() => {});
  reader = dec.readable.getReader();
  writer = port.writable.getWriter();
  reading = true;
  (async () => {
    while (reading) {
      const { value, done } = await reader.read();
      if (done) break;
      raw(value);
      if (!sawNsh && /nsh>\s*$/.test(value)) {
        sawNsh = true;
        setDot($('dNsh'), 'ok', '就绪', $('tNsh'));
        log('NSH 已就绪。');
      }
    }
  })().catch(() => {});

  log('串口已打开，板子会复位一次，等它起来…');
  // 等 nsh（最多 20 秒）
  for (let i = 0; i < 200 && !sawNsh; i++) await sleep(100);
  if (!sawNsh) {
    // 主动敲一下回车，有些情况下提示符需要一次输入才刷出来
    await write('');
    for (let i = 0; i < 60 && !sawNsh; i++) await sleep(100);
  }
  if (!sawNsh) {
    setDot($('dNsh'), 'bad', '没等到', $('tNsh'));
    log('没等到 nsh>：App 可能正在跑并占着控制台；若屏幕亮着就不用管。', 'warn');
  }

  if (sawNsh) {
    await sleep(300);
    const out = await psAndMaybeStart(autoStart);
    reportApp(out);
  }
}

let lastOut = '';
async function psAndMaybeStart(autoStart) {
  lastOut = '';
  const mark = logEl.textContent.length;
  await write('ps');
  await sleep(2200);
  let psOut = logEl.textContent.slice(mark);
  const running = /\bp4x_gs\b/.test(psOut) && /Task/.test(psOut);
  if (!running && autoStart) {
    log('p4x_gs 没在跑，拉起来：p4x_gs &');
    await write('p4x_gs &');
    await sleep(2500);
    const mark2 = logEl.textContent.length;
    await write('ps');
    await sleep(2200);
    psOut = logEl.textContent.slice(mark2);
  }
  return psOut;
}

function reportApp(psOut) {
  const running = /\bp4x_gs\b/.test(psOut) && /Task/.test(psOut);
  if (running) {
    setDot($('dApp'), 'ok', '运行中', $('tApp'));
    log('✅ p4x_gs 正在运行。');
    psOut.split('\n').filter(l => /p4x_gs|panel|lora_rx|tchsamp/.test(l))
      .forEach(l => log('   ' + l.trim()));
  } else {
    setDot($('dApp'), 'bad', '未运行', $('tApp'));
    log('❌ 没看到 p4x_gs 任务。可以点「重启 App」再试一次。', 'bad');
  }
}

async function statusOnly() {
  if (!writer) return;
  const out = await psAndMaybeStart(false);
  reportApp(out);
}

async function restartApp() {
  if (!writer) return;
  const mark = logEl.textContent.length;
  await write('ps');
  await sleep(2000);
  const out = logEl.textContent.slice(mark);
  const m = out.match(/^\s*(\d+)\s+\d+\s+\d+\s+\w+\s+\w+.*?\bp4x_gs\b/m);
  if (m) { log('停止 pid ' + m[1]); await write('kill ' + m[1]); await sleep(1500); }
  await write('p4x_gs &');
  await sleep(2500);
  const out2 = await psAndMaybeStart(false);
  reportApp(out2);
}

async function disconnect() {
  reading = false;
  try { await reader.cancel(); } catch (e) {}
  try { writer.releaseLock(); } catch (e) {}
  try { await port.close(); } catch (e) {}
  reader = writer = port = null;
  setDot($('dPort'), '', '未连接', $('tPort'));
  setDot($('dNsh'), '', '—', $('tNsh'));
  setDot($('dApp'), '', '—', $('tApp'));
  ['btnStatus', 'btnRestart', 'btnDisc'].forEach(i => $(i).disabled = true);
  $('btnConn').disabled = false;
  log('已断开。');
}

$('btnConn').onclick = () => connect($('autoStart').checked);
$('btnStatus').onclick = statusOnly;
$('btnRestart').onclick = restartApp;
$('btnDisc').onclick = disconnect;
$('btnClear').onclick = () => { logEl.textContent = ''; };
</script>
</body>
</html>","file_path":"C:\Users\HUAWEI\Desktop\P4X\web\p4x_web.html"}

