{"content":"# -*- coding: utf-8 -*-
"""P4X 地面站控制台（一个入口，什么都能干）

用法：
    python p4x.py            # 默认 up：确保 App 在跑；已在跑就重启一次（救黑屏）
    python p4x.py status     # 只看状态，不动
    python p4x.py start      # 只在没跑时启动
    python p4x.py restart    # 强制 kill + 重启（黑屏通常这样能亮）
    python p4x.py web        # 起本地网页服务并打开浏览器

为什么默认要重启：这块板子冷启动后经常"只有背光/全黑"，面板要重新走一遍
上电时序才亮，所以"点一下就能用"= 让 App 重新初始化一次面板。
"""
import io
import os
import re
import subprocess
import sys
import time
import webbrowser

import serial

PORT_HINT = "COM3"
BAUD = 115200
APP = "p4x_gs"
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
LOG = os.path.join(ROOT, "logs", "p4x_ctl.log")
WEB_DIR = os.path.join(ROOT, "web")


def say(msg=""):
    print(msg, flush=True)


def find_port():
    try:
        import serial.tools.list_ports as lp
        ports = list(lp.comports())
        for p in ports:
            if "303A:1001" in (p.hwid or "").upper():
                return p.device
        if ports:
            return ports[0].device
    except Exception:
        pass
    return PORT_HINT


def clean(raw):
    t = raw.decode("utf-8", "replace")
    t = re.sub(r"\x1b\[[0-9;?]*[A-Za-z]", "", t)
    return t.replace("\x00", "")


class Board(object):
    def __init__(self):
        self.port = find_port()
        self.buf = bytearray()
        self.s = serial.Serial(self.port, BAUD, timeout=0.2)
        try:
            self.s.setRTS(False)
            self.s.setDTR(False)
        except Exception:
            pass

    def pump(self, sec):
        t0 = time.time()
        while time.time() - t0 < sec:
            d = self.s.read(8192)
            if d:
                self.buf.extend(d)

    def text(self):
        return clean(self.buf)

    def cmd(self, line, wait=2.5):
        if line:
            self.s.write((line + "\n").encode())
        self.pump(wait)
        return self.text()

    def close(self):
        try:
            self.s.close()
        except Exception:
            pass


def app_running(txt):
    return bool(re.search(r"^\s*\d+\s+\d+\s+\d+\s+\w+\s+\w+.*?\b%s\b" % APP, txt, re.M))


def find_pid(txt):
    m = re.search(r"^\s*(\d+)\s+\d+\s+\d+\s+\w+\s+\w+.*?\b%s\b" % APP, txt, re.M)
    return m.group(1) if m else None


def show_tasks(txt):
    for line in txt.splitlines():
        if re.search(r"p4x_gs|panel|lora_rx|tchsamp", line):
            say("   " + line.strip()[:110])


def show_logs(txt, tail=10):
    keys = re.compile(r"ERR fb0|panel|dsi|lcd|backlight|P4X-|SD |tx=", re.I)
    hits = [l.strip() for l in txt.splitlines() if keys.search(l)]
    if hits:
        say("   最近日志：")
        for h in hits[-tail:]:
            say("   · " + h[:118])


def do_web():
    if not os.path.isdir(WEB_DIR):
        say("找不到 %s" % WEB_DIR)
        return 1
    url = "http://localhost:8765/p4x_web.html"
    try:
        subprocess.Popen([sys.executable, "-m", "http.server", "8765"],
                         cwd=WEB_DIR,
                         stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL,
                         creationflags=getattr(subprocess, "CREATE_NEW_CONSOLE", 0))
        time.sleep(0.8)
        webbrowser.open(url)
        say("已启动本地服务并打开：%s" % url)
        say("（网页服务在后台跑着；要关掉就关那个黑色窗口）")
        return 0
    except Exception as e:
        say("起服务失败：%s" % e)
        return 1


def main():
    action = (sys.argv[1] if len(sys.argv) > 1 else "up").lower()
    if action in ("web", "www", "网页"):
        return do_web()

    try:
        b = Board()
    except Exception as e:
        say("打不开串口：%s" % e)
        say("（板子插了吗？被串口助手/网页占着吗？）")
        return 2

    log = io.StringIO()
    try:
        say("连接 %s …（开串口会让板子复位一次，等约 15 秒）" % b.port)
        b.pump(7.0)
        for _ in range(3):                 # 敲回车唤醒 NSH；App 占着控制台也可能没反应
            b.s.write(b"\n")
            b.pump(0.7)

        txt = b.cmd("ps", 2.5)
        if "PID" not in txt or "COMMAND" not in txt:
            b.pump(2.0)
            txt = b.cmd("ps", 2.5)

        if "PID" not in txt or "COMMAND" not in txt:
            if re.search(r"P4X-|tx=\d+|STAT ", txt):
                say("✅ App 在跑（控制台被它占着，没回任务表）")
                show_logs(txt)
                return 0
            say("❌ NSH 没响应：板子可能还在启动，或串口被占用。等 10 秒再点一次。")
            return 1

        running = app_running(txt)
        pid = find_pid(txt)

        if action == "status":
            if running:
                say("✅ %s 正在运行（pid %s）" % (APP, pid))
            else:
                say("○ %s 没在运行" % APP)
            show_tasks(txt)
            return 0 if running else 1

        if running and action == "start":
            say("✅ 已经在运行（pid %s），不重复启动" % pid)
            show_tasks(txt)
            return 0

        if running and action in ("restart", "up", "rescue"):
            say("先停掉旧的（pid %s）…" % pid)
            b.cmd("kill %s" % pid, 1.6)
            b.pump(1.2)

        say("启动 %s …" % APP)
        b.cmd("%s &" % APP, 3.5)
        b.pump(2.0)
        txt = b.cmd("ps", 2.5)
        ok = app_running(txt)

        if ok:
            say("✅ 已启动，任务表：")
            show_tasks(txt)
            b.cmd("", 1.5)
            show_logs(b.text())
            say("屏幕如果还是黑的：再跑一次 restart；仍黑就是面板/排线问题（文档里有记录）。")
        else:
            say("❌ 没起来。看看下面的日志：")
            show_logs(b.text(), 16)
            say("常见原因：串口被占用 / 面板初始化失败(ERR fb0) / 上次崩溃没退干净。")
        return 0 if ok else 1
    finally:
        b.close()
        log.write(b.text())
        try:
            os.makedirs(os.path.dirname(LOG), exist_ok=True)
            with io.open(LOG, "w", encoding="utf-8") as f:
                f.write(log.getvalue())
        except Exception:
            pass


if __name__ == "__main__":
    sys.exit(main())","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\p4x.py"}

