{"content":"$ErrorActionPreference = 'Stop'
$src = 'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
$work = 'C:\Users\HUAWEI\Desktop\_ppt\work.pptx'
$dividers = @(3, 7, 13, 20, 25, 30)
$expect = 41
Copy-Item $src $work -Force

$pp = $null; $pres = $null
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($work, $false, $false, $false)
    Write-Output ("slides=" + $pres.Slides.Count)
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $t = $pres.Slides.Item($i).SlideShowTransition
        $t.AdvanceOnClick = -1
        if ($dividers -contains $i) { $t.EntryEffect = 3847 } else { $t.EntryEffect = 1793 }
        $t.Duration = 0.7
    }
    $pres.Save()
    Write-Output 'transitions saved'
} catch {
    Write-Output ("ERR apply: " + $_.Exception.Message)
} finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}

$pp = $null; $pres = $null
$ok = $false
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($work, $true, $false, $false)
    $tot = 0; $badTr = 0; $bad = @()
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $t = $pres.Slides.Item($i).SlideShowTransition
        $exp = 1793
        if ($dividers -contains $i) { $exp = 3847 }
        if ($t.EntryEffect -ne $exp) { $badTr++; $bad += "s$i" }
        $tot += $pres.Slides.Item($i).TimeLine.MainSequence.Count
    }
    $issues = @()
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        foreach ($sh in $pres.Slides.Item($i).Shapes) {
            try {
                if (-not $sh.HasTextFrame) { continue }
                if (-not $sh.TextFrame.HasText) { continue }
                $tr2 = $sh.TextFrame.TextRange
                if ([string]::IsNullOrWhiteSpace($tr2.Text)) { continue }
                if ($tr2.BoundHeight -gt $sh.Height + 14) {
                    $s = $tr2.Text -replace "`r", ' '
                    if ($s.Length -gt 26) { $s = $s.Substring(0, 26) }
                    $issues += ("s{0} {1:N0}>{2:N0} '{3}'" -f $i, $tr2.BoundHeight, $sh.Height, $s)
                }
            } catch {}
        }
    }
    Write-Output ("anim_total=" + $tot + " badTr=" + $badTr + " " + ($bad -join ','))
    Write-Output ("height_overflows=" + $issues.Count)
    $issues | Select-Object -First 8 | ForEach-Object { Write-Output ("  " + $_) }
    $ok = ($pres.Slides.Count -eq $expect) -and ($badTr -eq 0) -and ($tot -ge 800)
} catch {
    Write-Output ("ERR verify: " + $_.Exception.Message)
} finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}

if ($ok) {
    Copy-Item $work $src -Force
    Write-Output 'REPLACED deliverable'
} else {
    Write-Output 'KEPT python-built file'
}
Get-ChildItem $src | Select-Object Name, Length","file_path":"C:\Users\HUAWEI\Desktop\_ppt\com_finish.ps1"}

