{"content":"# -*- coding: utf-8 -*-
"""Minimal markdown -> HTML for the defense manual (enough for our syntax)."""
import html
import io
import re
import sys

SRC = sys.argv[1]
DST = sys.argv[2]

CSS = """
@page { size: A4; margin: 18mm 16mm; }
body { font-family: "Microsoft YaHei","Segoe UI",sans-serif; font-size: 10.5pt;
       line-height: 1.7; color: #1a1f26; }
h1 { font-size: 17pt; color: #0b5d3b; border-bottom: 2px solid #3ddc97;
     padding-bottom: 4px; margin-top: 22px; page-break-after: avoid; }
h2 { font-size: 13.5pt; color: #0f766e; margin-top: 18px; page-break-after: avoid; }
h3 { font-size: 11.5pt; color: #334155; margin-top: 14px; page-break-after: avoid; }
p  { margin: 6px 0; }
ul,ol { margin: 6px 0 6px 22px; }
li { margin: 3px 0; }
table { border-collapse: collapse; width: 100%; margin: 10px 0;
        font-size: 9.5pt; page-break-inside: avoid; }
th { background: #e8f7f0; border: 1px solid #9fcfbb; padding: 5px 7px;
     text-align: left; font-weight: 600; }
td { border: 1px solid #c8d6d0; padding: 5px 7px; vertical-align: top; }
tr:nth-child(even) td { background: #f7fbf9; }
code { font-family: Consolas,"Courier New",monospace; font-size: 9.5pt;
       background: #f1f5f9; padding: 1px 3px; border-radius: 3px; }
pre { font-family: Consolas,"Courier New",monospace; font-size: 9pt;
      background: #0f172a; color: #dbeafe; padding: 10px 12px; border-radius: 6px;
      white-space: pre-wrap; page-break-inside: avoid; }
pre code { background: none; color: inherit; padding: 0; }
blockquote { border-left: 4px solid #3ddc97; background: #f3fbf7;
             margin: 8px 0; padding: 8px 12px; color: #14532d; }
strong { color: #b91c1c; }
"""


def inline(text):
    text = html.escape(text)
    text = re.sub(r"`([^`]+)`", r"<code>\1</code>", text)
    text = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", text)
    return text


def convert(md):
    out = []
    lines = md.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        s = line.strip()

        if s.startswith("```"):
            i += 1
            buf = []
            while i < len(lines) and not lines[i].strip().startswith("```"):
                buf.append(html.escape(lines[i]))
                i += 1
            i += 1
            out.append("<pre><code>%s</code></pre>" % "\n".join(buf))
            continue

        if not s:
            i += 1
            continue

        m = re.match(r"^(#{1,6})\s+(.*)$", s)
        if m:
            lvl = len(m.group(1))
            out.append("<h%d>%s</h%d>" % (lvl, inline(m.group(2)), lvl))
            i += 1
            continue

        if s.startswith("|") and i + 1 < len(lines) and re.match(r"^\|[\s:\-|]+\|$", lines[i + 1].strip()):
            header = [c.strip() for c in s.strip("|").split("|")]
            i += 2
            rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                rows.append([c.strip() for c in lines[i].strip().strip("|").split("|")])
                i += 1
            out.append("<table><thead><tr>%s</tr></thead><tbody>%s</tbody></table>" % (
                "".join("<th>%s</th>" % inline(c) for c in header),
                "".join("<tr>%s</tr>" % "".join("<td>%s</td>" % inline(c) for c in r) for r in rows)))
            continue

        if s.startswith("> "):
            buf = []
            while i < len(lines) and lines[i].strip().startswith(">"):
                buf.append(lines[i].strip().lstrip(">").strip())
                i += 1
            out.append("<blockquote>%s</blockquote>" % inline(" ".join(buf)))
            continue

        if re.match(r"^[-*]\s+", s):
            buf = []
            while i < len(lines) and re.match(r"^[-*]\s+", lines[i].strip()):
                buf.append(re.sub(r"^[-*]\s+", "", lines[i].strip()))
                i += 1
            out.append("<ul>%s</ul>" % "".join("<li>%s</li>" % inline(b) for b in buf))
            continue

        if re.match(r"^\d+\.\s+", s):
            buf = []
            while i < len(lines) and re.match(r"^\d+\.\s+", lines[i].strip()):
                buf.append(re.sub(r"^\d+\.\s+", "", lines[i].strip()))
                i += 1
            out.append("<ol>%s</ol>" % "".join("<li>%s</li>" % inline(b) for b in buf))
            continue

        out.append("<p>%s</p>" % inline(s))
        i += 1
    return "\n".join(out)


