{"content":"$ErrorActionPreference = 'Stop'
$new  = 'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X_31页.pptx'
$canon = 'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
$dividers = @(3, 6, 11, 15, 20, 24)

$pp = $null; $pres = $null
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($new, $false, $false, $false)
    Write-Output ("slides=" + $pres.Slides.Count)

    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $s = $pres.Slides.Item($i)

        # ---- 转场 ----
        $tr = $s.SlideShowTransition
        $tr.AdvanceOnClick = -1
        if ($dividers -contains $i) { $tr.EntryEffect = 3847 } else { $tr.EntryEffect = 1793 }
        $tr.Duration = 0.7

        # ---- 入场动画（Fade，逐元素错峰）----
        $seq = $s.TimeLine.MainSequence
        for ($k = $seq.Count; $k -ge 1; $k--) { $seq.Item($k).Delete() }

        $shapes = @()
        foreach ($sh in $s.Shapes) {
            try {
                if ($sh.Width -lt 14 -or $sh.Height -lt 14) { continue }
                $hasText = $false
                try { $hasText = ($sh.HasTextFrame -and $sh.TextFrame.HasText) } catch {}
                if (-not $hasText -and $sh.Height -lt 45) { continue }
            } catch { continue }
            $shapes += $sh
        }
        $step = if ($shapes.Count -gt 22) { 0.07 } else { 0.13 }
        $first = $true; $delay = 0.0
        foreach ($sh in $shapes) {
            $trig = if ($first) { 1 } else { 2 }   # 1=点击时 2=与上一动画同时（配延迟错峰）
            try {
                $eff = $seq.AddEffect($sh, 10, 0, $trig)   # 10 = Fade
                $eff.Timing.Duration = 0.45
                if ($first) { $eff.Timing.TriggerDelayTime = 0.0 }
                else { $delay += $step; $eff.Timing.TriggerDelayTime = $delay }
            } catch {}
            $first = $false
        }
    }
    $pres.Save()
    Write-Output 'transitions + animations saved'
} catch {
    Write-Output ("ERR apply: " + $_.Exception.Message)
} finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}

# ---- 复核 ----
$pp = $null; $pres = $null
$ok = $false
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($new, $true, $false, $false)
    $tot = 0; $badTr = 0; $minAnim = 999
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $s = $pres.Slides.Item($i)
        $exp = if ($dividers -contains $i) { 3847 } else { 1793 }
        if ($s.SlideShowTransition.EntryEffect -ne $exp) { $badTr++ }
        $n = $s.TimeLine.MainSequence.Count
        $tot += $n
        if ($n -lt $minAnim) { $minAnim = $n }
    }
    $issues = @()
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        foreach ($sh in $pres.Slides.Item($i).Shapes) {
            try {
                if (-not $sh.HasTextFrame) { continue }
                if (-not $sh.TextFrame.HasText) { continue }
                $tr2 = $sh.TextFrame.TextRange
                if ([string]::IsNullOrWhiteSpace($tr2.Text)) { continue }
                if ($tr2.BoundHeight -gt $sh.Height + 16) {
                    $t = ($tr2.Text -replace "`r", ' ')
                    if ($t.Length -gt 22) { $t = $t.Substring(0, 22) }
                    $issues += ("s{0} '{1}'" -f $i, $t)
                }
            } catch {}
        }
    }
    Write-Output ("slides=" + $pres.Slides.Count + " anim_total=" + $tot + " min_anim_per_slide=" + $minAnim + " badTr=" + $badTr)
    Write-Output ("height_overflows=" + $issues.Count)
    if ($issues.Count -gt 0) { $issues | Select-Object -First 8 | ForEach-Object { Write-Output ("  " + $_) } }
    $ok = ($pres.Slides.Count -eq 31) -and ($badTr -eq 0) -and ($minAnim -ge 2)
} catch {
    Write-Output ("ERR verify: " + $_.Exception.Message)
} finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}

if ($ok) {
    try {
        Remove-Item $canon -Force -ErrorAction Stop
        Rename-Item $new '2026_openvela_答辩_P4X探空火箭双端遥测.pptx' -ErrorAction Stop
        Write-Output 'REPLACED canonical file (31 pages)'
    } catch {
        Write-Output ('REPLACE FAILED (keep both): ' + $_.Exception.Message)
    }
} else {
    Write-Output 'KEPT new file only'
}
