'@
$new = @'
    def __init__(self, i2c, addr=0x68):
        self.i2c = i2c
        self.addr = addr
        # ★ 必须校验 WHO_AM_I(0x75)：老版本把所有异常都吞掉，
        #   结果"根本没接"也会打印 MPU6050 OK（2026-10-27 实测踩到）。
        try:
            who = self.i2c.readfrom_mem(addr, 0x75, 1)[0]
        except Exception as e:
            raise OSError("not on bus (%s)" % e)
        if who not in (0x68, 0x70, 0x71, 0x73, 0x98):
            raise OSError("WHO_AM_I=0x%02X, not an MPU" % who)
        self.who = who
        try:
'@
if($t.Contains($old)){ $t = $t.Replace($old,$new); [System.IO.File]::WriteAllText((Resolve-Path $f), $t, (New-Object System.Text.UTF8Encoding($false))); 'patched' } else { 'anchor not found' }
