{"content":"$ErrorActionPreference = 'Stop'
$f = 'C:\Users\HUAWEI\Desktop\2026_openvela_答辩_P4X探空火箭双端遥测.pptx'
$dividers = @(3, 7, 12, 16, 21, 25)

$pp = $null; $pres = $null
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($f, $false, $false, $false)
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $t = $pres.Slides.Item($i).SlideShowTransition
        $t.AdvanceOnClick = -1
        if ($dividers -contains $i) { $t.EntryEffect = 3847 } else { $t.EntryEffect = 1793 }
        $t.Duration = 0.7
    }
    $pres.Save()
    Write-Output 'transitions fixed'
} catch { Write-Output ("ERR: " + $_.Exception.Message) } finally {
    if ($pres) { try { $pres.Close() } catch {} }
    if ($pp) { try { $pp.Quit() } catch {} }
}

$pp = $null; $pres = $null
try {
    $pp = New-Object -ComObject PowerPoint.Application
    $pres = $pp.Presentations.Open($f, $true, $false, $false)
    $bad = @(); $tot = 0
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $exp = if ($dividers -contains $i) { 3847 } else { 1793 }
        if ($pres.Slides.Item($i).SlideShowTransition.EntryEffect -ne $exp) { $bad += "s$i" }
        $tot += $pres.Slides.Item($i).TimeLine.MainSequence.Count
    }
    Write-Output ("slides=" + $pres.Slides.Count + " anim=" + $tot + " badTr=" + $bad.Count + " " + ($bad -join ','))
    # 打印每页首行标题，顺便确认顺序
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $title = ''
        foreach ($sh in $pres.Slides.Item($i).Shapes) {
            try {
                if ($sh.HasTextFrame -and $sh.TextFrame.HasText) {
