import os
try:
    print('SD 根目录:', os.listdir('/sd'))
except Exception as e:
    print('SD 未挂载:', e)
    import machine
    try:
        import sdcard
        spi = machine.SoftSPI(baudrate=200000, polarity=0, phase=0, sck=machine.Pin(5), mosi=machine.Pin(6), miso=machine.Pin(11, machine.Pin.IN, machine.Pin.PULL_UP))
        sd = sdcard.SDCard(spi, machine.Pin(7, machine.Pin.OUT), 200000)
        os.mount(sd, '/sd'); print('重新挂载 OK:', os.listdir('/sd'))
    except Exception as e2:
