"""从指定会话里抽取用户消息，用于人工确认项目归属与整理要点。"""
import json
import sys

import zstandard as zstd

SESS = sys.argv[1]
LIMIT = int(sys.argv[2]) if len(sys.argv) > 2 else 40

d = zstd.ZstdDecompressor().stream_reader(open(SESS, 'rb')).read().decode('utf-8', 'replace')

out = []
for line in d.splitlines():
    if '"role":"user"' not in line:
        continue
    try:
        o = json.loads(line)
    except Exception:
        continue
    msg = (o.get('data') or {}).get('message') or {}
    if msg.get('role') != 'user':
        continue
    content = msg.get('content')
    text = ''
    if isinstance(content, str):
        text = content
    elif isinstance(content, list):
        for c in content:
            if isinstance(c, dict) and c.get('type') == 'text':
                text += c.get('text', '')
    text = ' '.join(text.split())
    if text:
        out.append(text)

print('用户消息数 =', len(out))
for t in out[:LIMIT]:
    print('·', t[:110])","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\dump_session_user.py"}

