                if not r.font.size or not r.text.strip(): continue
                k=(round(r.font.size.pt,1), str(r.font.name), str(r.font.bold))
                seen[k]=seen.get(k,0)+1
print('最终 字号/字体/字重 组合:')
for k,v in sorted(seen.items(), key=lambda x:-x[1])[:10]:
    print('  %5.1fpt %-8s bold=%-6s x%d' % (k[0], k[1], k[2], v))
"","description":"Fall back Light to Regular and list final combos","timeoutMs":300000}

