"""列出 20pt 的文字，判断该归 15 还是 22；并列出所有非 MiSans 字体。"""
import re
import sys
import zipfile

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_最终_fixed.pptx'

z = zipfile.ZipFile(P)
print('=== 20pt 文本样本 ===')
n20 = 0
for n in sorted(z.namelist()):
    if not re.match(r'ppt/slides/slide\d+\.xml$', n):
        continue
    x = z.read(n).decode('utf-8', 'replace')
    for m in re.finditer(r'<a:rPr[^>]*?sz="2000"[^>]*?>', x):
        seg = x[m.start():m.start() + 1400]
        tm = re.search(r'<a:t>([^<]{0,40})', seg)
        if tm and n20 < 12:
            print('  %-24s %s' % (n.split('/')[-1], tm.group(1)))
            n20 += 1

print('\n=== 非 MiSans 字体 ===')
for n in z.namelist():
    if not n.endswith('.xml'):
        continue
    x = z.read(n).decode('utf-8', 'replace')
    for m in re.finditer(r'<a:(latin|ea|cs) typeface="([^"]+)"', x):
        if m.group(2) not in ('MiSans',):
            print('  %-26s %-4s %s' % (n.split('/')[-1], m.group(1), m.group(2)))
z.close()","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\list_20pt.py"}

