import sys; sys.stdout.reconfigure(encoding='utf-8',errors='replace')
from pptx import Presentation
p=Presentation(r'C:\Users\HUAWEI\Desktop\P4X_提交_给主办方\P4X_答辩_PPT_最终_v2.pptx')
sizes={}; bold={}
for s in p.slides:
    for sh in s.shapes:
        if not sh.has_text_frame: continue
        for para in sh.text_frame.paragraphs:
            for r in para.runs:
                if not r.font.size: continue
                k=round(r.font.size.pt,1); sizes[k]=sizes.get(k,0)+1
                bold[(k,bool(r.font.bold))]=bold.get((k,bool(r.font.bold)),0)+1
print('字号分布:', dict(sorted(sizes.items())))
print('关键档位:', {k: sizes.get(k,0) for k in (15,22,30,46,72)})
print('22pt 加粗数:', bold.get((22,True),0), ' 30pt 加粗数:', bold.get((30,True),0))
