{"content":"# -*- coding: utf-8 -*-
"""P4X 地面站：火箭 3D 姿态改用重力向量定向（消除万向锁）

旧做法：roll → pitch → yaw 依次旋转欧拉角。
        箭体竖直时 pitch≈±90°，此时"左右倾斜"在数学上落到 roll 上，
        模型就只会"绕轴自转"，看起来像倒了却只是在转。

新做法：用遥测里的 ax/ay/az（单位 g，体坐标下的重力方向）
        配合 Rodrigues 公式求一个旋转，把体坐标的"重力方向"转到世界的"向下"，
        于是无论竖直 / 平放 / 倾斜，模型都显示真实的倾倒方向；
        再在这根轴上叠加 roll 自转（视觉上由条纹与尾翼体现），最后叠 yaw 绕世界竖轴。
"""

import io

P = r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD = '''  /* ---- roll about the body axis, then pitch, then yaw ----------------- */

  for (i = 0; i < nv; i++)
    {
      float x = mx[i];
      float y = my[i];
      float z = mz[i];
      float t;

      t = x * cr - z * sr;             /* roll  (about the body axis) */
      z = x * sr + z * cr;
      x = t;

      t = y * cp - z * sp;             /* pitch */
      z = y * sp + z * cp;
      y = t;

      t = x * cyw + z * syw;           /* yaw */
      z = -x * syw + z * cyw;
      x = t;

      wx[i] = x;
      wy[i] = y;
      wz[i] = z;
    }
'''

NEW = '''  /* ---- P4X-ATT3: 用重力向量定向（不再用欧拉角，消除万向锁） ------------
   *
   * 遥测里的 ax/ay/az 是"重力在箭体坐标下的方向"（单位 g）。
   * 只要让这块"体坐标的重力方向"对齐到世界的"向下"，模型的倾倒方向就是对的，
   * 竖直姿态下也不会退化成"只会自转"。
   *
   *   a  = normalize(ax, ay, az)        体坐标的重力方向
   *   b  = (0, -1, 0)                   世界坐标的向下（屏幕 y 向下为正）
   *   R  = Rodrigues(a → b)
   *   v' = R( roll_spin(v) ) 再叠 yaw 绕世界竖轴
   */

  {
    float gx3 = fl.ax, gy3 = fl.ay, gz3 = fl.az;
    float gn3 = sqrtf(gx3 * gx3 + gy3 * gy3 + gz3 * gz3);
    float a1 = 0.0f, a2 = -1.0f, a3 = 0.0f;   /* 单位重力（体坐标），默认向下 */
    float kx, ky, kz, kk;                     /* 旋转轴（未归一） */
    float sn, cs, inv_k;
    int   use_gravity = 1;

    if (gn3 > 0.3f && gn3 < 3.0f)
      {
        a1 = gx3 / gn3;
        a2 = gy3 / gn3;
        a3 = gz3 / gn3;
      }
    else
      {
        use_gravity = 0;      /* 失重/异常：保持原来的欧拉角做法 */
      }

    if (use_gravity)
      {
        /* axis = a × b,  b = (0,-1,0)  =>  (a3, 0, -a1) */
        kx = a3;
        ky = 0.0f;
        kz = -a1;
        kk = sqrtf(kx * kx + ky * ky + kz * kz);
        cs = -a2;                        /* cos(角) = a·b */
        sn = kk;                         /* sin(角) */

        if (kk > 1e-5f)
          {
            kx /= kk;
            ky /= kk;
            kz /= kk;
            inv_k = 1.0f;
          }
        else
          {
            /* 平行：a≈b 不动；a≈-b 绕 X 转 180° */
            if (cs > 0.0f)
              {
                kx = 1.0f; ky = 0.0f; kz = 0.0f; sn = 0.0f;
              }
            else
              {
                kx = 1.0f; ky = 0.0f; kz = 0.0f; sn = 0.0f; cs = -1.0f;
              }
            inv_k = 1.0f;
          }

        for (i = 0; i < nv; i++)
          {
            float x = mx[i];
            float y = my[i];
            float z = mz[i];
            float t;
            float d, cxv, cyv, czv;

            /* 1) roll：绕体轴（模型 +Y）自转 */
            t = x * cr - z * sr;
            z = x * sr + z * cr;
            x = t;

            /* 2) Rodrigues：把体坐标的"向下"转到世界向下 */
            d = kx * x + ky * y + kz * z;                 /* axis·v */
            cxv = ky * z - kz * y;                        /* axis×v */
            cyv = kz * x - kx * z;
            czv = kx * y - ky * x;

            x = x * cs + cxv * sn + kx * d * (1.0f - cs);
            y = y * cs + cyv * sn + ky * d * (1.0f - cs);
            z = z * cs + czv * sn + kz * d * (1.0f - cs);

            /* 3) yaw：绕世界竖轴（屏幕 Y）转，表现偏航 */
            t = x * cyw + z * syw;
            z = -x * syw + z * cyw;
            x = t;

            wx[i] = x;
            wy[i] = y;
            wz[i] = z;
          }
      }
    else
      {
        for (i = 0; i < nv; i++)
          {
            float x = mx[i];
            float y = my[i];
            float z = mz[i];
            float t;

            t = x * cr - z * sr;
            z = x * sr + z * cr;
            x = t;

            t = y * cp - z * sp;
            z = y * sp + z * cp;
            y = t;

            t = x * cyw + z * syw;
            z = -x * syw + z * cyw;
            x = t;

            wx[i] = x;
            wy[i] = y;
            wz[i] = z;
          }
      }
  }
'''

if OLD in s:
    s = s.replace(OLD, NEW, 1)
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('P4X-ATT3 补丁已写入')
else:
    print('锚点未找到，未修改')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_p4_att3.py"}

