{"content":"# -*- coding: utf-8 -*-
"""P4X-FASTROCKET：姿态页只重绘模型区（420×420），大幅提高刷新率

背景：整页 1024×600 的推送要 300–400 ms，所以 8 Hz 的数据看起来像 2–3 fps。
做法：新增 rocket_model_fast()，把卡片背景与模型画进 back buffer，
      但只把模型周围 420×420 的矩形拷到 fb 并 FBIO_UPDATE；
      每 16 帧退回一次整页重绘，保证右侧数字与其它元素不长期不更新。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

# ---------- 1) 新增 fast 函数，插在 page_rocket 之后 ----------
ANCHOR = '''/****************************************************************************
 * Page 4 · 雷达页（网页端第 3 页）
 ****************************************************************************/'''

FAST = '''/****************************************************************************
 * P4X-FASTROCKET: 姿态页快速重绘（只推模型周围的一块）
 ****************************************************************************/

static void rocket_model_fast(void)
{
  struct fb_area_s area;
  int x = CONT_X;
  int y = CONT_Y;
  int w = CONT_W;
  int h = CONT_H;
  int rw = 420;
  int cw = w - rw - 8;
  int cx = x + cw / 2;
  int cy = y + h / 2 + 20;
  int mx = cx - 210;
  int my = cy - 210;
  int mw = 420;
  int mh = 420;
  int row;

  if (bb == NULL || fb == NULL)
    {
      return;
    }

  /* 卡片底与模型都画进 back buffer */
  card(x, y, cw, h, 0);
  draw_rocket3d(cx, cy, fl.yaw, fl.pitch, fl.roll,
                fl.phase == 2 || fl.phase == 3);

  /* 边界裁剪 */
  if (mx < 0) { mw += mx; mx = 0; }
  if (my < 0) { mh += my; my = 0; }
  if (mx + mw > fb_w) { mw = fb_w - mx; }
  if (my + mh > fb_h) { mh = fb_h - my; }
  if (mw <= 0 || mh <= 0)
    {
      return;
    }

  for (row = 0; row < mh; row++)
    {
      size_t off = ((size_t)(my + row) * (size_t)fb_stride + (size_t)mx) * 2u;

      memcpy((uint8_t *)fb + off, (uint8_t *)bb + off, (size_t)mw * 2u);
    }

  area.x = mx;
  area.y = my;
  area.w = mw;
  area.h = mh;
  (void)ioctl(fb_fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&area));
}

/****************************************************************************
 * Page 4 · 雷达页（网页端第 3 页）
 ****************************************************************************/'''

if 'rocket_model_fast' in s:
    print('fast 函数已存在，跳过')
elif ANCHOR in s:
    s = s.replace(ANCHOR, FAST, 1)
    print('插入 rocket_model_fast ok')
else:
    print('MISS anchor')

# ---------- 2) 在页面分发处接入 ----------
OLD_DISPATCH = '''            switch (cur_page)
              {
                case 0: page_status();  break;
                case 1: page_curves();  break;
                case 2: page_speed();   break;
                case 3: page_rocket();  break;
                default: page_radar();  break;
              }'''

NEW_DISPATCH = '''            /* P4X-FASTROCKET: 姿态页只重画模型区（约 420×420），
             * 每 16 帧才退回一次整页，保证数字与其他元素也会更新。
             */

            {
              static int rk_n;

              if (cur_page == 3 && !page_clear_req && !g_shade_drag &&
                  g_shade_h == g_shade_target && (++rk_n % 16) != 0)
                {
                  rocket_model_fast();
                }
              else
                {
                  switch (cur_page)
                    {
                      case 0: page_status();  break;
                      case 1: page_curves();  break;
                      case 2: page_speed();   break;
                      case 3: page_rocket();  break;
                      default: page_radar();  break;
                    }
                }
            }'''

if OLD_DISPATCH in s:
    s = s.replace(OLD_DISPATCH, NEW_DISPATCH, 1)
    print('接入分发 ok')
else:
    print('MISS dispatch')

io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
print('written')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_fastrocket.py"}

