const AI_URL = 'http://127.0.0.1:8766';
const aiHist = [];
let aiBusy = false;

function aiSay(text) {
  $('aiA').textContent = text;
}

async function aiHealth() {
  try {
    const r = await fetch(AI_URL + '/health', { cache: 'no-store' });
    const j = await r.json();
    setDot($('dAi'), j.key ? 'ok' : 'wait', j.key ? '在线 · ' + j.model : '在线(无Key)', $('tAi'));
    return j;
  } catch (e) {
    setDot($('dAi'), 'bad', '未启动', $('tAi'));
    return null;
  }
}

// 从串口日志里挖现场数据，作为 AI 的上下文
function aiContext() {
  const txt = logEl.textContent || '';
  const lines = txt.split('\n').filter(l => l.trim());
  const pick = [];
  const stat = lines.filter(l => /STAT |tx=|lora=|junk=|fix=|sat=|phase=/.test(l)).slice(-6);
  pick.push(...stat);
  pick.push(...lines.slice(-25));
  const board = ['板载任务：' + (lines.some(l => /p4x_gs/.test(l)) ? 'p4x_gs 在跑' : '未见 p4x_gs')];
  return (board.concat(pick)).join('\n').slice(-3500);
}

async function aiAsk(q) {
  q = (q || '').trim();
  if (!q) { aiSay('先写个问题吧。'); return; }
  if (aiBusy) return;
  aiBusy = true;
  $('btnAiAsk').disabled = true;
  aiSay('思考中…');
  try {
    const body = { q, ctx: aiContext(), history: aiHist.slice(-4) };
    const r = await fetch(AI_URL + '/ask', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const j = await r.json();
    if (j.ok) {
      aiSay(j.answer);
      aiHist.push({ role: 'user', text: q }, { role: 'assistant', text: j.answer });
    } else {
      aiSay('调用失败：' + (j.error || '未知错误') + '\n（确认 网页启动.bat 里的 AI 服务窗口还在）');
    }
  } catch (e) {
    aiSay('连不上 AI 服务。双击 网页启动.bat（它会同时启动页面服务与 AI 服务），再刷新本页。');
  } finally {
    aiBusy = false;
    $('btnAiAsk').disabled = false;
  }
}

$('btnAiAsk').onclick = () => aiAsk($('aiQ').value);
$('aiQ').addEventListener('keydown', e => { if (e.key === 'Enter') aiAsk($('aiQ').value); });
document.querySelectorAll('.chip[data-q]').forEach(c => {
  c.style.cursor = 'pointer';
  c.onclick = () => { $('aiQ').value = c.dataset.q; aiAsk(c.dataset.q); };
});
$('btnAiCtx').onclick = () => aiAsk('用下面的现场数据，判断链路、传感器、姿态是否正常，指出最值得关注的一点，并给出下一步建议');
$('btnAiClear').onclick = () => { $('aiA').textContent = '助手待命。'; aiHist.length = 0; };
aiHealth();

$('btnConn').onclick = () => connect($('autoStart').checked);","old_string":"$('btnConn').onclick = () => connect($('autoStart').checked);"}

