/* =====================================================================
 * P4X 融合模块：① 连接 P4X 并启动  ② AI 多轮问答
 * 说明：AI 走本地代理 http://127.0.0.1:8766（Key 只在后端，前端拿不到）
 * ===================================================================== */

/* ---------- 抽屉开关 ---------- */
const p4xDrawer = document.getElementById('p4xDrawer');
const aiDrawer  = document.getElementById('aiDrawer');
document.getElementById('p4xBtn').addEventListener('click', () => {
  p4xDrawer.classList.toggle('open');
  aiDrawer.classList.remove('open');
  if (!p4xConnected) p4xConnect();
});
document.getElementById('aiBtn').addEventListener('click', () => {
  aiDrawer.classList.toggle('open');
  p4xDrawer.classList.remove('open');
  if (aiDrawer.classList.contains('open')) setTimeout(() => document.getElementById('chatIn').focus(), 220);
});
document.getElementById('p4xClose').addEventListener('click', () => p4xDrawer.classList.remove('open'));
document.getElementById('aiClose').addEventListener('click', () => aiDrawer.classList.remove('open'));

/* ---------- ① 连接 P4X：选口 → 等 NSH → 检查/拉起 p4x_gs ---------- */
let p4xPort = null, p4xWriter = null, p4xReader = null, p4xConnected = false;
const p4xLogEl = document.getElementById('p4xLog');

function p4xLog(msg) {
  p4xLogEl.textContent += '\n' + msg;
  p4xLogEl.scrollTop = p4xLogEl.scrollHeight;
}
function p4xState(cls, text) {
  const b = document.getElementById('p4xBtn');
  b.className = cls; b.textContent = text;
}
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function p4xWrite(s) {
  if (!p4xWriter) return;
  await p4xWriter.write(new TextEncoder().encode(s + '\r\n'));
}

async function p4xConnect() {
  if (p4xConnected) { p4xDrawer.classList.add('open'); return; }
  if (!('serial' in navigator)) {
    p4xLog('这个浏览器不支持 WebSerial，用 Chrome/Edge 打开；并且要用 http://localhost 而不是 file://');
    p4xState('err', '不支持 WebSerial');
    return;
  }
  try {
    p4xState('busy', '选择串口…');
    p4xLog('请在弹出的列表里选 ESP32-P4（303A:1001，通常显示为 USB 设备）');
    p4xPort = await navigator.serial.requestPort({ filters: [{ usbVendorId: 0x303A }] });
    await p4xPort.open({ baudRate: 115200 });
    p4xWriter = p4xPort.writable.getWriter();
    p4xConnected = true;
    p4xState('busy', '等待 NSH…');
    p4xLog('已打开串口。开串口会让板子复位一次，等它自己起来（约 12 秒）…');

    // 起一个读线程，把输出打到抽屉里，同时检测 nsh>
    p4xReader = p4xPort.readable.getReader();
    const dec = new TextDecoder();
    let buf = '';
    const t0 = Date.now();
    (async () => {
      try {
        while (true) {
          const { value, done } = await p4xReader.read();
          if (done) break;
          const s = dec.decode(value, { stream: true });
          buf += s;
          p4xLogEl.textContent += s.replace(/\r/g, '');
          p4xLogEl.scrollTop = p4xLogEl.scrollHeight;
          if (buf.length > 8000) buf = buf.slice(-4000);
        }
      } catch (e) { /* 断开 */ }
    })();

    // 等 NSH，最多 40 秒
    await p4xWrite('');
    while (Date.now() - t0 < 40000) {
      if (/nsh>\s*$/.test(buf) || /NuttShell/.test(buf)) break;
      await sleep(500);
      await p4xWrite('');
    }
    if (!/nsh>|NuttShell/.test(buf)) {
      p4xState('err', 'NSH 未响应');
      p4xLog('没等到 NSH。检查：串口是否选错、板子是否上电、有没有被其它程序占用。');
      return;
    }

    p4xLog('NSH 已就绪，检查 p4x_gs …');
    p4xState('busy', '检查 App…');
    await p4xWrite('ps');
    await sleep(2000);
    const tail = buf.slice(-4000);
    if (/\bp4x_gs\b/.test(tail) && /Task/.test(tail)) {
      p4xLog('p4x_gs 已在运行。');
    } else {
      p4xLog('p4x_gs 没在跑，拉起它：p4x_gs &');
      await p4xWrite('p4x_gs &');
      await sleep(3000);
    }
    p4xState('ok', 'P4X 已就绪');
    p4xLog('完成。可以开始演示。');
  } catch (e) {
    p4xState('err', '连接失败');
    p4xLog('连接失败：' + (e && e.message ? e.message : e));
  }
}

document.getElementById('p4xPs').addEventListener('click', async () => {
  if (!p4xConnected) { p4xLog('还没连上 P4X。'); return; }
  await p4xWrite('ps');
  await sleep(1800);
});
document.getElementById('p4xRestart').addEventListener('click', async () => {
  if (!p4xConnected) { p4xLog('还没连上 P4X。'); return; }
  p4xLog('重启 App：kill 旧 pid → 重新拉起来');
  const mark = p4xLogEl.textContent.length;
  await p4xWrite('ps');
  await sleep(1800);
  const out = p4xLogEl.textContent.slice(mark);
  const m = out.match(/^\s*(\d+)\s+\d+\s+\d+\s+\w+\s+\w+.*?\bp4x_gs\b/m);
  if (m) { await p4xWrite('kill ' + m[1]); await sleep(1200); }
  await p4xWrite('p4x_gs &');
  await sleep(2500);
  p4xLog('已重启。');
});

/* ---------- ② AI 多轮问答 ---------- */
const AI_URL = 'http://127.0.0.1:8766';
const chatList = document.getElementById('chatList');
const chatIn = document.getElementById('chatIn');
const chatSend = document.getElementById('chatSend');
let aiHistory = [];      // [{role:'user'|'assistant', text}]
let aiBusy = false;

document.getElementById('aiBtn').addEventListener('click', () => {
  fetch(AI_URL + '/health', { cache: 'no-store' })
    .then(r => r.json())
    .then(j => {
      document.getElementById('aiBtn').classList.toggle('on', !!j.key);
      if (!j.key) aiBubble('bot', 'AI 服务在线，但后端没配 Key（环境变量或 ~/.dsh/.credentials.yaml）。');
    })
    .catch(() => aiBubble('err', '连不上 AI 服务。请先双击 web 目录里的「启动助手.bat」（它会起 8766 代理），再刷新本页。'));
});

function aiBubble(role, text) {
  const d = document.createElement('div');
  d.className = 'msg ' + (role === 'user' ? 'user' : role === 'err' ? 'err' : 'bot');
  const who = document.createElement('span');
  who.className = 'who';
  who.textContent = role === 'user' ? '我' : role === 'err' ? '系统' : 'AI';
  d.appendChild(who);
  d.appendChild(document.createTextNode(text));
  chatList.appendChild(d);
  chatList.scrollTop = chatList.scrollHeight;
  return d;
}

// 把页面上的实时数值整理成上下文，喂给模型
function aiSnapshot() {
  const g = id => (document.getElementById(id) || {}).textContent || '--';
  const lines = [
    '【当前遥测】',
    '高度(m): ' + g('altVal'),
    '速度(m/s): ' + g('velVal'),
    '卫星数: ' + g('satVal'),
    '阶段: ' + g('phaseVal'),
    'T+ (s): ' + g('timeVal'),
    'LoRa: ' + (document.getElementById('loraDot').style.background.includes('00ff') ? '通' : '断'),
  ];
  try {
    if (typeof data === 'object' && data) {
      lines.push('内部状态: pitch=' + (data.pitch ?? '-') + ' roll=' + (data.roll ?? '-') +
                 ' yaw=' + (data.yaw ?? '-') + ' ax=' + (data.ax ?? '-') +
                 ' ay=' + (data.ay ?? '-') + ' az=' + (data.az ?? '-'));
    }
  } catch (e) {}
  if (typeof p4xLogEl !== 'undefined' && p4xLogEl && p4xLogEl.textContent) {
    lines.push('【P4X 控制台尾部】', p4xLogEl.textContent.slice(-1200));
  }
  return lines.join('\n');
}

async function aiAsk(q) {
  q = (q || '').trim();
  if (!q || aiBusy) return;
  aiBusy = true; chatSend.disabled = true;
  aiBubble('user', q);
  const pending = aiBubble('bot', '思考中…');
  try {
    const r = await fetch(AI_URL + '/ask', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ q, ctx: aiSnapshot(), history: aiHistory.slice(-6) })
    });
    const j = await r.json();
    pending.remove();
    if (j.ok) {
      aiBubble('bot', j.answer);
      aiHistory.push({ role: 'user', text: q }, { role: 'assistant', text: j.answer });
      if (aiHistory.length > 20) aiHistory = aiHistory.slice(-20);
    } else {
      aiBubble('err', '调用失败：' + (j.error || '未知错误'));
    }
  } catch (e) {
    pending.remove();
    aiBubble('err', '连不上 AI 服务（8766）。先运行「启动助手.bat」，再刷新。');
  } finally {
    aiBusy = false; chatSend.disabled = false; chatIn.value = '';
  }
}

chatSend.addEventListener('click', () => aiAsk(chatIn.value));
chatIn.addEventListener('keydown', e => { if (e.key === 'Enter') aiAsk(chatIn.value); });
document.querySelectorAll('#chatBtns button').forEach(b => {
  b.addEventListener('click', () => aiAsk(b.dataset.q));
});
document.getElementById('aiNew').addEventListener('click', () => {
  aiHistory = [];
  chatList.innerHTML = '';
  aiBubble('bot', '新对话开始。');
