/* ---------- ① 连接 P4X：选口 → 等 NSH → 检查/拉起 p4x_gs ---------- */
let p4xPort = null, p4xWriter = null, p4xReader = null, p4xConnected = false;
const p4xLogEl = document.getElementById('p4xLog');

function p4xLog(msg) {
  p4xLogEl.textContent += '\n' + msg;
  p4xLogEl.scrollTop = p4xLogEl.scrollHeight;
}
function p4xState(cls, text) {
  const b = document.getElementById('p4xBtn');
  b.className = cls; b.textContent = text;
}
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function p4xWrite(s) {
  if (!p4xWriter) return;
  await p4xWriter.write(new TextEncoder().encode(s + '\r\n'));
}

async function p4xConnect() {
  if (p4xConnected) { p4xDrawer.classList.add('open'); return; }
  if (!('serial' in navigator)) {
    p4xLog('这个浏览器不支持 WebSerial，用 Chrome/Edge 打开；并且要用 http://localhost 而不是 file://');
    p4xState('err', '不支持 WebSerial');
    return;
  }
  try {
    p4xState('busy', '选择串口…');
    p4xLog('请在弹出的列表里选 ESP32-P4（303A:1001，通常显示为 USB 设备）');
    p4xPort = await navigator.serial.requestPort({ filters: [{ usbVendorId: 0x303A }] });
    await p4xPort.open({ baudRate: 115200 });
    p4xWriter = p4xPort.writable.getWriter();
    p4xConnected = true;
    p4xState('busy', '等待 NSH…');
    p4xLog('已打开串口。开串口会让板子复位一次，等它自己起来（约 12 秒）…');

    // 起一个读线程，把输出打到抽屉里，同时检测 nsh>
    p4xReader = p4xPort.readable.getReader();
    const dec = new TextDecoder();
    let buf = '';
    const t0 = Date.now();
    (async () => {
      try {
        while (true) {
          const { value, done } = await p4xReader.read();
          if (done) break;
          const s = dec.decode(value, { stream: true });
          buf += s;
          p4xLogEl.textContent += s.replace(/\r/g, '');
          p4xLogEl.scrollTop = p4xLogEl.scrollHeight;
          if (buf.length > 8000) buf = buf.slice(-4000);
        }
      } catch (e) { /* 断开 */ }
    })();

    // 等 NSH，最多 40 秒
    await p4xWrite('');
    while (Date.now() - t0 < 40000) {
      if (/nsh>\s*$/.test(buf) || /NuttShell/.test(buf)) break;
      await sleep(500);
      await p4xWrite('');
    }
    if (!/nsh>|NuttShell/.test(buf)) {
      p4xState('err', 'NSH 未响应');
      p4xLog('没等到 NSH。检查：串口是否选错、板子是否上电、有没有被其它程序占用。');
      return;
    }

    p4xLog('NSH 已就绪，检查 p4x_gs …');
    p4xState('busy', '检查 App…');
    await p4xWrite('ps');
    await sleep(2000);
    const tail = buf.slice(-4000);
    if (/\bp4x_gs\b/.test(tail) && /Task/.test(tail)) {
      p4xLog('p4x_gs 已在运行。');
    } else {
      p4xLog('p4x_gs 没在跑，拉起它：p4x_gs &');
      await p4xWrite('p4x_gs &');
      await sleep(3000);
    }
    p4xState('ok', 'P4X 已就绪');
    p4xLog('完成。可以开始演示。');
  } catch (e) {
    p4xState('err', '连接失败');
    p4xLog('连接失败：' + (e && e.message ? e.message : e));
  }
}

