          if (done) break;
          const s = dec.decode(value, { stream: true });
          buf += s;
          p4xLogEl.textContent += s.replace(/\r/g, '');
          p4xLogEl.scrollTop = p4xLogEl.scrollHeight;
          if (buf.length > 8000) buf = buf.slice(-4000);
        }
      } catch (e) { /* 断开 */ }
    })();

    // 等 NSH，最多 40 秒
    await p4xWrite('');
    while (Date.now() - t0 < 40000) {
      if (/nsh>\s*$/.test(buf) || /NuttShell/.test(buf)) break;
      await sleep(500);
      await p4xWrite('');
    }
    if (!/nsh>|NuttShell/.test(buf)) {
      p4xState('err', 'NSH 未响应');
      p4xLog('没等到 NSH。检查：串口是否选错、板子是否上电、有没有被其它程序占用。');
      return;
    }

    p4xLog('NSH 已就绪，检查 p4x_gs …');
    p4xState('busy', '检查 App…');
    await p4xWrite('ps');
    await sleep(2000);
    const tail = buf.slice(-4000);
    if (/\bp4x_gs\b/.test(tail) && /Task/.test(tail)) {
      p4xLog('p4x_gs 已在运行。');
    } else {
      p4xLog('p4x_gs 没在跑，拉起它：p4x_gs &');
      await p4xWrite('p4x_gs &');
      await sleep(3000);
    }
    p4xState('ok', 'P4X 已就绪');
    p4xLog('完成。可以开始演示。');
  } catch (e) {
    p4xState('err', '连接失败');
    p4xLog('连接失败：' + (e && e.message ? e.message : e));
  }
}

document.getElementById('p4xPs').addEventListener('click', async () => {
