/* ---------- ② AI 多轮问答 ---------- */
const AI_URL = 'http://127.0.0.1:8766';
const chatList = document.getElementById('chatList');
const chatIn = document.getElementById('chatIn');
const chatSend = document.getElementById('chatSend');
let aiHistory = [];      // [{role:'user'|'assistant', text}]
let aiBusy = false;

document.getElementById('aiBtn').addEventListener('click', () => {
  fetch(AI_URL + '/health', { cache: 'no-store' })
    .then(r => r.json())
    .then(j => {
      document.getElementById('aiBtn').classList.toggle('on', !!j.key);
      if (!j.key) aiBubble('bot', 'AI 服务在线，但后端没配 Key（环境变量或 ~/.dsh/.credentials.yaml）。');
    })
    .catch(() => aiBubble('err', '连不上 AI 服务。请先双击 web 目录里的「启动助手.bat」（它会起 8766 代理），再刷新本页。'));
});

function aiBubble(role, text) {
  const d = document.createElement('div');
  d.className = 'msg ' + (role === 'user' ? 'user' : role === 'err' ? 'err' : 'bot');
  const who = document.createElement('span');
  who.className = 'who';
  who.textContent = role === 'user' ? '我' : role === 'err' ? '系统' : 'AI';
  d.appendChild(who);
  d.appendChild(document.createTextNode(text));
  chatList.appendChild(d);
  chatList.scrollTop = chatList.scrollHeight;
  return d;
}

// 把页面上的实时数值整理成上下文，喂给模型
function aiSnapshot() {
  const g = id => (document.getElementById(id) || {}).textContent || '--';
  const lines = [
    '【当前遥测】',
    '高度(m): ' + g('altVal'),
    '速度(m/s): ' + g('velVal'),
    '卫星数: ' + g('satVal'),
    '阶段: ' + g('phaseVal'),
    'T+ (s): ' + g('timeVal'),
    'LoRa: ' + (document.getElementById('loraDot').style.background.includes('00ff') ? '通' : '断'),
  ];
  try {
    if (typeof data === 'object' && data) {
      lines.push('内部状态: pitch=' + (data.pitch ?? '-') + ' roll=' + (data.roll ?? '-') +
                 ' yaw=' + (data.yaw ?? '-') + ' ax=' + (data.ax ?? '-') +
                 ' ay=' + (data.ay ?? '-') + ' az=' + (data.az ?? '-'));
    }
  } catch (e) {}
  if (typeof p4xLogEl !== 'undefined' && p4xLogEl && p4xLogEl.textContent) {
    lines.push('【P4X 控制台尾部】', p4xLogEl.textContent.slice(-1200));
  }
  return lines.join('\n');
}

async function aiAsk(q) {
  q = (q || '').trim();
  if (!q || aiBusy) return;
  aiBusy = true; chatSend.disabled = true;
  aiBubble('user', q);
  const pending = aiBubble('bot', '思考中…');
  try {
    const r = await fetch(AI_URL + '/ask', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ q, ctx: aiSnapshot(), history: aiHistory.slice(-6) })
    });
    const j = await r.json();
    pending.remove();
    if (j.ok) {
      aiBubble('bot', j.answer);
      aiHistory.push({ role: 'user', text: q }, { role: 'assistant', text: j.answer });
      if (aiHistory.length > 20) aiHistory = aiHistory.slice(-20);
    } else {
      aiBubble('err', '调用失败：' + (j.error || '未知错误'));
    }
  } catch (e) {
    pending.remove();
    aiBubble('err', '连不上 AI 服务（8766）。先运行「启动助手.bat」，再刷新。');
  } finally {
    aiBusy = false; chatSend.disabled = false; chatIn.value = '';
  }
}

chatSend.addEventListener('click', () => aiAsk(chatIn.value));
chatIn.addEventListener('keydown', e => { if (e.key === 'Enter') aiAsk(chatIn.value); });
document.querySelectorAll('#chatBtns button').forEach(b => {
  b.addEventListener('click', () => aiAsk(b.dataset.q));
});
document.getElementById('aiNew').addEventListener('click', () => {
  aiHistory = [];
  chatList.innerHTML = '';
  aiBubble('bot', '新对话开始。');
});
</script>
</body>
</html>

