{"content":"# -*- coding: utf-8 -*-
"""P4X-JSONECHO：把每帧遥测按网页能直接解析的格式回显到 USB 控制台。

背景：网页 dashboard.html 只认 `{...}` 单行 JSON，并且用的是长键
      （alt / v / p / r / y / ax / ay / az / sat / phase / lora / temp / press / time / gps）。
      而箭载端发的是短键（a / s / ph / P / T），P4 解析后只存在内存里给屏幕用，
      从不外发 —— 于是"接上了 P4 但网页没数据"。

做法：在 telemetry_apply_json() 成功收下一帧后，按网页的键名打印一行。
      每 2 帧打一次（约 4 Hz），控制台只占约 0.7 KB/s。
"""
import io
import sys

P = sys.argv[1] if len(sys.argv) > 1 else r'C:\Users\HUAWEI\Desktop\P4X\src\p4x_gs_main.c'
s = io.open(P, encoding='utf-8', errors='replace').read()

OLD = '''  if (ok >= 2)
    {
      telemetry_live = 1;
      lora_packets++;
'''

NEW = '''  if (ok >= 2)
    {
      telemetry_live = 1;
      lora_packets++;

      /* P4X-JSONECHO: 给网页用的回显（长键名，与 dashboard.html 的 parseJSON 对齐）。
       * 每 2 帧发一次，约 4 Hz；约 0.7 KB/s，不会压住控制台。
       */

      {
        static int echo_n;

        if ((++echo_n & 1) == 0)
          {
            printf("{\\"alt\\":%.2f,\\"v\\":%.2f,\\"p\\":%.2f,\\"r\\":%.2f,"
                   "\\"y\\":%.2f,\\"ax\\":%.2f,\\"ay\\":%.2f,\\"az\\":%.2f,"
                   "\\"sat\\":%d,\\"phase\\":%d,\\"lora\\":1,\\"temp\\":%.1f,"
                   "\\"press\\":%.0f,\\"time\\":\\"%s\\",\\"gps\\":%d}\\n",
                   (double)fl.alt, (double)fl.v, (double)fl.pitch, (double)fl.roll,
                   (double)fl.yaw, (double)fl.ax, (double)fl.ay, (double)fl.az,
                   fl.sat, fl.phase, (double)fl.temperature,
                   (double)fl.pressure, fl.time_str, fl.gps_fix);
          }
      }
'''

if 'P4X-JSONECHO' in s:
    print('已打过补丁')
elif OLD in s:
    s = s.replace(OLD, NEW, 1)
    io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
    print('JSONECHO 已插入')
else:
    print('MISS 锚点')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_jsonecho.py"}

