"""把控制台按钮接到主连接上：不再单独 requestPort，命令直接写主串口。"""
import io
import re

P = r'G:\HuaweiMoveData\Users\HUAWEI\Desktop\contest2026_465_chuangkonghangtian\web\dashboard.html'
s = io.open(P, encoding='utf-8').read()

# 1) p4xWrite 改用主连接的 port（临时取 writer）
OLD_W = """async function p4xWrite(s) {
  if (!p4xWriter) return;
  await p4xWriter.write(new TextEncoder().encode(s + '\\r\\n'));
}"""
NEW_W = """async function p4xWrite(cmd) {
  // 复用主连接的那条串口（connBtn 打开的那条），不再单独开端口
  if (!port || !port.writable) { p4xLog('还没连上，先点顶栏「连接 P4X」。'); return false; }
  try {
    const w = port.writable.getWriter();
    await w.write(new TextEncoder().encode(cmd + '\\r\\n'));
    w.releaseLock();
    p4xLog('→ ' + cmd);
    return true;
  } catch (e) {
    p4xLog('写串口失败: ' + e.message);
    return false;
  }
}"""
if OLD_W in s:
    s = s.replace(OLD_W, NEW_W, 1)
    print('p4xWrite 已改为复用主连接')
else:
    print('未找到旧 p4xWrite')

# 2) 「查任务」按钮
s = re.sub(r"document\.getElementById\('p4xPs'\)\.addEventListener\('click', async \(\) => \{[^}]*\}\);",
           """document.getElementById('p4xPs').addEventListener('click', async () => {
  await p4xWrite('ps');
});""", s, count=1)

# 3) 「重启 App」按钮
s = re.sub(r"document\.getElementById\('p4xRestart'\)\.addEventListener\('click', async \(\) => \{.*?\n\}\);",
           """document.getElementById('p4xRestart').addEventListener('click', async () => {
  p4xLog('重启 p4x_gs：先 ps 找 pid，再 kill，最后重新拉起');
  await p4xWrite('ps');
  await sleep(1500);
  const m = p4xLogEl.textContent.slice(-3000).match(/^\\s*(\\d+)\\s+\\d+\\s+\\d+\\s+\\w+\\s+\\w+.*?\\bp4x_gs\\b/m);
  if (m) { await p4xWrite('kill ' + m[1]); await sleep(1200); }
  await p4xWrite('p4x_gs &');
});""", s, count=1, flags=re.S)

io.open(P, 'w', encoding='utf-8', newline='\n').write(s)
print('按钮已改为走主连接')","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\patch_console_unify.py"}

