  // 不再单独 requestPort —— 否则会二次弹选口、而且两条串口不能同时开同一个设备。
  if (!port || !port.writable) {
    p4xLog('还没连上板子，先点顶栏「连接 P4X」。');
    return false;
  }
  try {
    const w = port.writable.getWriter();
    await w.write(new TextEncoder().encode(cmd + '\r\n'));
    w.releaseLock();
    p4xLog('→ ' + cmd);
    return true;
  } catch (e) {
    p4xLog('写串口失败：' + e.message);
    return false;
  }
}

