{"content":""""直接监听 GPS 串口 12 秒：打印 GGA 定位质量、可见星 CN0、是否频繁掉定位。

用法：mpremote connect COM13 run tools/gps_probe.py
"""
import machine
import time

uart = machine.UART(1, baudrate=115200, tx=machine.Pin(4), rx=machine.Pin(10),
                    rxbuf=2048)

t0 = time.ticks_ms()
buf = b""
gga = []
gsv = {}
rmc = []
while time.ticks_diff(time.ticks_ms(), t0) < 12000:
    data = uart.read(256)
    if not data:
        time.sleep_ms(20)
        continue
    buf += data
    while b"\n" in buf:
        line, buf = buf.split(b"\n", 1)
        try:
            s = line.decode("ascii", "ignore").strip()
        except Exception:
            continue
        if not s.startswith("$"):
            continue
        p = s.split(",")
        tag = p[0][3:]
        if tag == "GGA" and len(p) > 9:
            gga.append((p[6], p[7], p[8], p[9]))
        elif tag == "GSV" and len(p) > 7:
            key = p[0][1:3]
            prn = []
            i = 4
            while i + 3 < len(p):
                try:
                    prn.append(int(p[i + 3]))
                except Exception:
                    pass
                i += 4
            gsv.setdefault(key, []).append((p[3], prn))
        elif tag == "RMC" and len(p) > 3:
            rmc.append(p[2])

print("=== 采样 12 秒 ===")
print("GGA 句数:", len(gga), " RMC 句数:", len(rmc))
if gga:
    q = [g[0] for g in gga]
    used = [g[1] for g in gga]
    print("定位质量(0=无效 1=单点 2=差分):", sorted(set(q)))
    print("参与定位星数范围:", min(used), "-", max(used))
    print("最后一句 GGA: 质量=%s 星数=%s HDOP=%s 高度=%s" % gga[-1])
if gsv:
    for k, v in gsv.items():
        tot = max((int(x[0]) for x in v), default=0)
        cn0 = [c for _, prns in v for c in prns]
        cn0 = [c for c in cn0 if c > 0]
        print("星座 %s: 视野内 %d 颗, 最强 CN0=%s, 平均 CN0=%.0f, 样本句 %d" %
              (k, tot, max(cn0) if cn0 else "-",
               (sum(cn0) / len(cn0)) if cn0 else 0, len(v)))
if rmc:
    print("RMC 状态位集合:", sorted(set(rmc)))

# 判断是否频繁掉定位
if gga:
    flips = 0
    prev = gga[0][0]
    for g in gga[1:]:
        if g[0] != prev:
            flips += 1
            prev = g[0]
    print("定位状态切换次数(12 秒内):", flips, "(>2 就是抖动)")","file_path":"C:\Users\HUAWEI\Desktop\P4X\tools\gps_probe.py"}

